  border-radius: 8px;
  background: #1B2034;
  color: #F4F6FF;
  cursor: pointer;
  scroll-margin: 6px;
  transition: border-color 120ms ease;
}

.card:hover {
  border-color: #F4F6FF;
}

.card:focus-visible {
  outline: 3px solid #FFFFFF;
  outline-offset: 2px;
}

.card-face {
  background: #111625;
}

.card-matched,
.card-matched:hover {
  border-color: #8BEA7D;
  cursor: default;
}

.card svg {
  display: block;
  width: 100%;
  height: 100%;
}

.matched-check {
  position: absolute;
  right: 4px;
  bottom: 1px;
  color: #8BEA7D;
  font-size: 14px;
  line-height: 16px;
}

@media (prefers-reduced-motion: reduce) {
  .card {
    transition: none;
  }
}

