/work/src/game/session/useGameSession.ts.content:
import { useEffect, useRef, useState } from "react";
import { createGame, makeBoardCode, MAX_SEED, parseBoardCode } from "../boardCode.ts";
import { encodeSnapshot, decodeSnapshot } from "../snapshot.ts";
import { activateCard, advanceGame, isWon, matchedPairs } from "../transitions.ts";
import { formatElapsed } from "../clock.ts";
import type { GameState, BoardSize } from "../types.ts";
import { readBestScores, readSavedSize, recordBest, saveSize, type BestScores } from "./storage.ts";

function randomSeed(): number {
  try {
    const value = window.crypto.getRandomValues(new Uint32Array(1))[0];
    if (value !== undefined) return (value % MAX_SEED) + 1;
  } catch {
    // Use a local fallback if secure randomness is unavailable.
  }
  return Math.floor(Math.random() * MAX_SEED) + 1;
}

function freshGame(size: BoardSize): GameState {
  const game = createGame(makeBoardCode(size, randomSeed()));
  if (!game) throw new Error("Could not create a new deal.");
  return game;
}

function initialGame(): GameState {
  return freshGame(readSavedSize());
}

export function useGameSession() {
  const [game, setGame] = useState(initialGame);
  const [bestScores, setBestScores] = useState<BestScores>(() => readBestScores());
  const [paused, setPaused] = useState(false);
  const [celebrate, setCelebrate] = useState(false);
  const [resetToken, setResetToken] = useState(0);
  const [status, setStatus] = useState("");
  const [announcement, setAnnouncement] = useState("");
  const [announcementId, setAnnouncementId] = useState(0);
  const gameRef = useRef(game);
  const pausedRef = useRef(false);
  const lastActiveAt = useRef<number | null>(null);

  function commit(next: GameState): void {
    gameRef.current = next;
    setGame(next);
  }

  function announce(message: string): void {
    setAnnouncement(message);
    setAnnouncementId((value) => value + 1);
  }

  function showStatus(message: string): void {
    setStatus(message);
    announce(message);
  }

  function syncClock(): GameState {
    const current = gameRef.current;
    if (document.hidden || pausedRef.current || !current.started || isWon(current)) return current;
    const now = performance.now();
    const last = lastActiveAt.current;
    if (last === null) {
      lastActiveAt.current = now;
      return current;
    }
    const elapsed = Math.floor(now - last);
    if (elapsed < 1) return current;
    lastActiveAt.current = last + elapsed;
    const next = advanceGame(current, elapsed);
    commit(next);
    return next;
  }

  useEffect(() => {
    let timer: number | undefined;
    const schedule = (delay: number) => { timer = window.setTimeout(tick, delay); };
    const tick = () => {
      const current = gameRef.current;
      if (document.hidden || pausedRef.current || !current.started || isWon(current)) {
        lastActiveAt.current = null;
        schedule(100);
        return;
      }
      const now = performance.now();
      const last = lastActiveAt.current;
      if (last === null) lastActiveAt.current = now;
      else {
        const elapsed = Math.floor(now - last);
        if (elapsed > 0) {
          lastActiveAt.current = last + elapsed;
          commit(advanceGame(current, elapsed));
        }
      }
      const next = gameRef.current;
      const delay = next.selection.kind === "mismatch"
        ? Math.min(25, next.selection.remainingMs)
        : 100;
      schedule(delay);
    };
    const visibilityChanged = () => {
      if (document.hidden) lastActiveAt.current = null;
      else if (gameRef.current.started && !pausedRef.current && !isWon(gameRef.current)) {
        lastActiveAt.current = performance.now();
      }
    };
    document.addEventListener("visibilitychange", visibilityChanged);
    schedule(25);
    return () => {
      if (timer !== undefined) window.clearTimeout(timer);
      document.removeEventListener("visibilitychange", visibilityChanged);
    };
  }, []);

  function replaceGame(next: GameState): void {
    commit(next);
    pausedRef.current = false;
    setPaused(false);
    setCelebrate(false);
    lastActiveAt.current = null;
    setResetToken((value) => value + 1);
  }

  function newGame(): void {
    replaceGame(freshGame(gameRef.current.size));
  }

  function restart(): void {
    const next = createGame(gameRef.current.boardCode);
    if (next) replaceGame(next);
  }

  function chooseSize(size: BoardSize): void {
    if (size === gameRef.current.size) return;
    saveSize(size);
    replaceGame(freshGame(size));
  }

  function activate(index: number): void {
    const current = syncClock();
    if (pausedRef.current) return;
    const isSecondReveal = current.selection.kind === "one" &&
      current.selection.index !== index && !current.matched.includes(index);
    const next = activateCard(current, index);
    if (next === current) return;
    commit(next);
    if (!current.started && next.started) lastActiveAt.current = performance.now();

    if (isSecondReveal) {
      if (next.matched.length > current.matched.length) {
        const pairs = matchedPairs(next);
        if (isWon(next)) {
          setCelebrate(true);
          setBestScores(recordBest(bestScores, next.size, next.moves));
          announce("Pair found. All pairs found in " + next.moves + " moves and " +
            formatElapsed(next.elapsedMs) + ".");
        } else {
          announce("Pair found. " + pairs + (pairs === 1 ? " pair matched." : " pairs matched."));
        }
      } else {
        announce("No match. Cards close after a short pause.");
      }
    }
    if (isWon(next)) lastActiveAt.current = null;
  }

  function loadBoard(draft: string): void {
    const parsed = parseBoardCode(draft.trim());
    const next = parsed ? createGame(parsed.boardCode) : null;
    if (!next) {
      showStatus("Invalid board code.");
      return;
    }
    saveSize(next.size);
    replaceGame(next);
    showStatus("Loaded board " + next.boardCode + ".");
  }

  function loadSnapshot(draft: string): void {
    const next = decodeSnapshot(draft);
    if (!next) {
      showStatus("Invalid snapshot.");
      return;
    }
    commit(next);
    const waiting = !isWon(next);
    pausedRef.current = waiting;
    setPaused(waiting);
    setCelebrate(false);
    lastActiveAt.current = null;
    setResetToken((value) => value + 1);
    saveSize(next.size);
    showStatus(waiting
      ? "Loaded snapshot. Select Resume to continue."
      : "Loaded completed snapshot.");
  }

  function exportSnapshot(): string {
    const current = gameRef.current;
    let snapshot = current;
    if (!document.hidden && !pausedRef.current && current.started && !isWon(current)) {
      const last = lastActiveAt.current;
      const now = performance.now();
      if (last !== null) {
        const elapsed = Math.floor(now - last);
        if (elapsed > 0) {
          lastActiveAt.current = last + elapsed;
          snapshot = advanceGame(current, elapsed);
        }
      }
    }
    showStatus("Snapshot exported.");
    return encodeSnapshot(snapshot);
  }

  function resume(): void {
    if (!pausedRef.current) return;
    pausedRef.current = false;
    setPaused(false);
    lastActiveAt.current = performance.now();
  }

  return {
    game,
    best: bestScores[game.size],
    paused,
    celebrate,
    resetToken,
    status,
    announcement,
    announcementId,
    newGame,
    restart,
    chooseSize,
    activate,
    loadBoard,
    loadSnapshot,
    exportSnapshot,
    resume,
  };
}

