  for (let column = fromColumn; column > toColumn; column -= 1) await page.keyboard.press("ArrowLeft");
}

test("plays a complete 4x4 game with keyboard and exposes its accessible board", async ({ page }) => {
  await page.goto("/");
  await loadSeedOne(page);
  await expect(page.getByLabel("Grid size")).toHaveValue("4");
  await expect(page.getByRole("button", { name: "New Game" })).toBeVisible();
  await page.getByLabel("Grid size").focus();
  await page.keyboard.press("Tab");
  await expect(page.getByRole("button", { name: "New Game" })).toBeFocused();
  await page.keyboard.press("Tab");
  await page.keyboard.press("Tab");

  const board = page.getByRole("group", { name: "Card board" });
  const tree = await board.ariaSnapshot();
  expect(tree).toContain('button "Row 1, column 1, closed"');
  await expect(page.getByRole("button", { name: "Row 1, column 1, closed" })).toBeFocused();

  const pairs: ReadonlyArray<readonly [number, number]> = [
    [0, 11], [1, 9], [2, 6], [3, 7], [4, 5], [8, 15], [10, 14], [12, 13],
  ];
  let position = 0;
  for (const [first, second] of pairs) {
    await moveFocus(page, position, first);
    await page.keyboard.press("Space");
    await moveFocus(page, first, second);
    await page.keyboard.press("Space");
    position = second;
  }
  await expect(page.getByText("Pairs: 8/8")).toBeVisible();
  await expect(page.getByText("Best: 8")).toBeVisible();
  await expect(page.getByRole("region", { name: "Game complete" })).toContainText("8 moves in");
  await expect(page.getByRole("status")).toContainText("All pairs found in 8 moves and");
  await page.reload();
  await expect(page.getByText("Best: 8")).toBeVisible();
});

test("board codes, misses and Restart isolate earlier timer work", async ({ page }) => {
  await page.goto("/");
  await loadSeedOne(page);
  const cards = page.getByRole("group", { name: "Card board" }).getByRole("button");
  const first = cards.nth(0);
  const second = page.getByRole("button", { name: "Row 1, column 2, closed" });
  await first.click();
  await expect(first).toHaveAccessibleName("Row 1, column 1, cyan solid plus, marker top, revealed");
  await second.click();
  await expect(page.getByText("Moves: 1")).toBeVisible();
  await expect(page.getByRole("status")).toHaveText("No match. Cards close after a short pause.");

  await page.getByRole("button", { name: "Restart" }).click();
  const restarted = page.getByRole("group", { name: "Card board" }).getByRole("button").nth(0);
  await restarted.click();
  await page.waitForTimeout(850);
  await expect(restarted).toHaveAccessibleName("Row 1, column 1, cyan solid plus, marker top, revealed");
  await expect(page.getByText("Moves: 0")).toBeVisible();
});

test("snapshot import pauses, Resume focuses the board, and export captures progress", async ({ page }) => {
  await page.goto("/");
  await loadSeedOne(page);
  const snapshot = JSON.stringify({
    version: 1, boardCode: "np1-4-1", matched: [],
    selection: { kind: "mismatch", first: 0, second: 1, remainingMs: 300 },
    moves: 1, elapsedMs: 500, started: true,
  });
  await page.getByLabel("Snapshot JSON").fill(snapshot);
  await page.getByRole("button", { name: "Load snapshot" }).click();
  await expect(page.locator(".load-status")).toHaveText("Loaded snapshot. Select Resume to continue.");
  await expect(page.getByRole("button", { name: "Resume" })).toBeVisible();
  const first = page.getByRole("group", { name: "Card board" }).getByRole("button").nth(0);
  await expect(first).toHaveAccessibleName("Row 1, column 1, cyan solid plus, marker top, revealed");
  await first.click();
  await expect(page.getByText("Moves: 1")).toBeVisible();
  await page.getByRole("button", { name: "Resume" }).click();
  await expect(first).toBeFocused();
  await expect(page.getByRole("button", { name: "Resume" })).toHaveCount(0);
  await expect(first).toHaveAccessibleName("Row 1, column 1, closed", { timeout: 1_000 });

  await page.getByRole("button", { name: "Export snapshot" }).click();
  const exported = JSON.parse(await page.getByLabel("Snapshot JSON").inputValue()) as {
    version: number; boardCode: string; moves: number;
  };
  expect(exported).toMatchObject({ version: 1, boardCode: "np1-4-1", moves: 1 });
});

test("a hidden page pauses the active mismatch interval", async ({ page }) => {
  await page.goto("/");
  await loadSeedOne(page);
  const cards = page.getByRole("group", { name: "Card board" }).getByRole("button");
  await cards.nth(0).click();
  await cards.nth(1).click();
  await expect(cards.nth(0)).toHaveAccessibleName("Row 1, column 1, cyan solid plus, marker top, revealed");
  await expect(cards.nth(1)).toHaveAccessibleName("Row 1, column 2, cyan solid chevron, marker top, revealed");
  await page.evaluate(() => {
    let hidden = false;
    Object.defineProperty(document, "hidden", {
      configurable: true,
      get: () => hidden,
    });
    window.setTestHidden = (value: boolean) => {
      hidden = value;
      document.dispatchEvent(new Event("visibilitychange"));
    };
  });
  await page.evaluate(() => window.setTestHidden(true));
  await page.waitForTimeout(850);
  await expect(cards.nth(0)).toHaveAccessibleName("Row 1, column 1, cyan solid plus, marker top, revealed");
  await page.evaluate(() => window.setTestHidden(false));
  await expect(cards.nth(0)).toHaveAccessibleName("Row 1, column 1, closed", { timeout: 1_500 });
});

test("completed snapshots stay static and do not replace best scores", async ({ page }) => {
  await page.goto("/");
  await page.getByText("Reproduce a game", { exact: true }).click();
  const snapshot = JSON.stringify({
    version: 1,
    boardCode: "np1-4-1",
    matched: Array.from({ length: 16 }, (_, index) => index),
    selection: { kind: "closed" },
    moves: 8,
    elapsedMs: 1_234,
    started: true,
  });
  await page.getByLabel("Snapshot JSON").fill(snapshot);
  await page.getByRole("button", { name: "Load snapshot" }).click();
  await expect(page.locator(".load-status")).toHaveText("Loaded completed snapshot.");
  await expect(page.getByRole("button", { name: "Resume" })).toHaveCount(0);
  await expect(page.locator(".win-banner")).not.toHaveClass(/win-banner-pulse/);
  await expect(page.getByText("Best: none")).toBeVisible();
});

test("the size preference persists on a local HTTP origin", async ({ page }) => {
  await page.goto("/");
  await page.getByLabel("Grid size").selectOption("6");
  await expect(page.getByLabel("Grid size")).toHaveValue("6");
  await page.reload();
  await expect(page.getByLabel("Grid size")).toHaveValue("6");
});

test("a 16x16 board scrolls inside a narrow phone viewport", async ({ page }) => {
  await page.setViewportSize({ width: 360, height: 800 });
  await page.goto("/");
  await page.getByLabel("Grid size").selectOption("16");
  const board = page.getByRole("group", { name: "Card board" });
  const cards = board.getByRole("button");
  await expect(cards).toHaveCount(256);
  const firstWidth = await cards.nth(0).evaluate((element) => element.getBoundingClientRect().width);
  expect(firstWidth).toBeGreaterThanOrEqual(44);
  const dimensions = await page.locator(".board-scroll").evaluate((element) => ({
    clientWidth: element.clientWidth,
    scrollWidth: element.scrollWidth,
  }));
  expect(dimensions.scrollWidth).toBeGreaterThan(dimensions.clientWidth);
  expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBeLessThanOrEqual(360);

  await cards.nth(0).focus();
  for (let row = 0; row < 15; row += 1) await page.keyboard.press("ArrowDown");
  for (let column = 0; column < 15; column += 1) await page.keyboard.press("ArrowRight");
  await expect(cards.nth(255)).toBeFocused();
});

test("the bundled HTML opens directly from disk", async ({ browser }) => {
  const context = await browser.newContext();
  await context.setOffline(true);
  const page = await context.newPage();
  await page.goto(pathToFileURL(resolve("dist/index.html")).href);
  await expect(page.getByRole("heading", { name: "Neon Pairs" })).toBeVisible();
  await expect(page.getByLabel("Grid size")).toHaveValue("4");
  await context.close();
});
# Neon Pairs
Neon Pairs is an offline browser memory game. It includes reproducible board codes, progress snapshots and a replay CLI.

Read the [game specification](docs/README.md) and its linked requirements.

## Build and run

Use Node.js 24.19 or later with npm.

```sh
npm ci
npm run dev
npm run typecheck
npm test
npm run test:e2e
npm run build
```

The build writes a self-contained `dist/index.html`. Open it directly from disk to play offline. Use a local HTTP origin when checking saved preferences.

Replay a version 1 replay file with:

```sh
npm run --silent replay -- PATH
```

Valid input prints the final snapshot JSON. Invalid input prints an error to stderr and exits nonzero.

## Verification record

Verified 2026-11-04 with Node.js 26.12.1, npm 11.20.0, Playwright 1.64.1 and Chromium 156.0.8078.4. The locked install passed; type checking passed; all 18 unit tests passed; all 8 Playwright journeys passed; and the production build emitted the offline HTML. The browser journeys covered keyboard play and completion, saved bests and size preferences, mismatch timing and restart, paused and completed snapshots, a 16x16 narrow viewport, and direct offline file loading.

Automated accessibility-tree evidence is included in the Playwright journey. A screen reader was not used; spoken output remains a user acceptance check.
